"""Regression tests for webgpt page review routing and verdict parsing."""

from __future__ import annotations

import pathlib
import sys

THIS_DIR = pathlib.Path(__file__).resolve().parent
SRC_DIR = THIS_DIR.parent / "src"
if str(SRC_DIR) not in sys.path:
    sys.path.insert(0, str(SRC_DIR))

from ask.ask_routing import _parse_webgpt_page_review_query
from ask.webgpt_page_review import build_adjudication_prompt, extract_page_review_verdict


def test_parse_review_page_coverage_round():
    matched, page_id, round_label, run_ti, suffix, force = _parse_webgpt_page_review_query(
        ["/review-page", "coverage", "round", "2", "run-ti", "capture-suffix", "-r2"]
    )
    assert matched is True
    assert page_id == "coverage"
    assert round_label == "2"
    assert run_ti is True
    assert suffix == "-r2"
    assert force is False


def test_parse_review_page_quoted():
    matched, page_id, _, _, _, _ = _parse_webgpt_page_review_query(
        ["/review-page chat round 1"]
    )
    assert matched is True
    assert page_id == "chat"


def test_parse_no_match():
    matched, _, _, _, _, _ = _parse_webgpt_page_review_query(["review this page"])
    assert matched is False


def test_extract_page_review_verdict():
    text = (
        "VERDICT: NEEDS_CHANGES\n"
        "PAGE_VERDICT: degraded\n"
        "NEXT_STEP: IMPLEMENT\n"
    )
    verdict, page_verdict, next_step = extract_page_review_verdict(text)
    assert verdict == "NEEDS_CHANGES"
    assert page_verdict == "degraded"
    assert next_step == "IMPLEMENT"


def test_build_adjudication_prompt_includes_page():
    prompt = build_adjudication_prompt(
        {"page": "coverage", "title": "Coverage", "persona_id": "nico-bailon"}
    )
    assert "coverage" in prompt
    assert "VERDICT:" in prompt
